package com.digihori.pgp.desktop.wav

import com.digihori.pgp.core.api.MachineMemoryLayout
import com.digihori.pgp.core.rom.MachineId
import com.digihori.pgp.core.wav.*
import com.digihori.pgp.desktop.basic.*
import java.io.File
import java.security.MessageDigest
import kotlinx.serialization.json.*

/** Public synthetic fixtures generated by Studio's encoder; no ROM or hardware recording required. */
fun main(args: Array<String>) {
    when (args.firstOrNull()) {
        "generate" -> generateHardwareFixtures(File(args[1]))
        "check" -> checkHardwareRecording(File(args[1]), File(args[2]))
        else -> error("Use generate <empty-directory> or check <case-directory> <recording.wav>")
    }
}

private val fixtureJson = Json { prettyPrint = true }
private fun ByteArray.hex() = joinToString("") { (it.toInt() and 255).toString(16).padStart(2, '0') }
private fun ByteArray.sha256() = MessageDigest.getInstance("SHA-256").digest(this).hex()
private fun body(result: DesktopWavResult): ByteArray = (result.payload?.body ?: result.s1Payload?.body ?: result.s1BasicPayload?.body ?: result.s2BasicPayload?.body ?: error(result.report())).copyBytes()
private fun address(result: DesktopWavResult): Int? = result.payload?.startAddress ?: result.s1Payload?.startAddress
private fun requireValid(result: DesktopWavResult) {
    check(result.error == null && result.program != null && result.diagnostics.none { it.severity != CodecDiagnosticSeverity.INFO }) { result.report() }
}
private fun writeJson(file: File, data: JsonObject) = file.writeText(fixtureJson.encodeToString(JsonObject.serializer(), data) + "\n")

private fun basicBody(source: String, machine: MachineId): ByteArray {
    val compiled = DesktopBasicLoader.compileProgram(source.encodeToByteArray(), machine)
    check(compiled is DesktopBasicProgramCompileResult.Success) { compiled.toString() }
    return when (machine.value) {
        "pc-1245" -> (DesktopOldBasicTransferAdapter.toTransferBody(compiled.bytes) as DesktopOldBasicTransferResult.Success).bytes
        else -> (S1BasicCodec.toTransferBody(compiled.bytes) as CodecResult.Success).value.copyBytes()
    }
}
private fun boundarySource(size: Int, machine: MachineId, family: String): String {
    // Keep each source line short enough for the PC-1401 editor, even for a 241-byte body.
    for (prefixLines in 0..10) for (padding in 0..50) {
        val source = buildString {
            append("10 PRINT \"$family OK\"\n20 END\n")
            repeat(prefixLines) { append("${(it + 3) * 10} REM " + "A".repeat(24) + "\n") }
            append("${(prefixLines + 3) * 10} REM " + "A".repeat(padding) + "\n")
        }
        if (runCatching { basicBody(source, machine).size == size }.getOrDefault(false)) return source
    }
    error("Cannot make $size-byte BASIC body for ${machine.value}")
}

private fun generateHardwareFixtures(root: File) {
    root.mkdirs()
    check(root.listFiles().orEmpty().isEmpty()) { "Output directory must be empty; preserve existing results and choose a new directory" }
    val index = mutableListOf("id,machine,kind,type,body_bytes,start_hex,end_hex,priority,file")
    for ((family, target) in listOf("OLD" to "pc-1245", "S1" to "pc-1401", "S2" to "pc-1360k")) {
        val machine = MachineId(target)
        val old = family == "OLD"
        val start = MachineMemoryLayout(machine).assemblyStartAddress
        data class Input(val id: String, val binary: Boolean, val text: String, val protected: Boolean = false, val priority: String = "P0")
        val basicSize = if (old) 169 else 241
        val binarySize = if (old) 168 else 240
        val pattern = ByteArray(binarySize) { index -> when (index % 8) {
            0 -> 0; 1 -> 0x0f; 2 -> 0xf0.toByte(); 3 -> 0xff.toByte(); else -> (index * 37 + 11).toByte()
        } }
        val inputs = listOf(
            Input("basic", false, boundarySource(basicSize, machine, family)),
            Input("binary", true, DesktopWavBinaryFiles.writeHex(start, pattern).decodeToString()),
        )
        for (input in inputs) {
            val id = "${family.lowercase()}-${input.id}"
            val name = "W" + (if (old) "1245" else if (family == "S1") "1401" else "1360") + (if (input.binary) "B" else "A")
            val encoded = DesktopWavOperation.encode(input.text.encodeToByteArray(), input.binary, machine, name, input.protected)
            val wav = encoded.wav ?: error("$id: ${encoded.report()}")
            val decoded = DesktopWavOperation.decode(wav, machine)
            requireValid(decoded)
            val logical = body(decoded)
            if (!input.binary) check(basicBody(input.text, machine).contentEquals(logical)) { "$id: target tokens differ from Studio's canonical dialect" }
            val raw = decoded.raw!!.copyBytes()
            val dir = File(root, id).apply { mkdirs() }
            File(dir, "send.wav").writeBytes(wav.copyBytes())
            File(dir, if (input.binary) "source.hex" else "source.bas").writeText(input.text)
            File(dir, "expected-body.bin").writeBytes(logical)
            File(dir, "expected-transfer.raw").writeBytes(raw)
            File(dir, if (input.binary) "expected-return.dmp" else "expected-return.bas").writeBytes(decoded.program!!)
            if (!input.binary) {
                val compiled = DesktopBasicLoader.compileProgram(input.text.encodeToByteArray(), machine) as DesktopBasicProgramCompileResult.Success
                File(dir, "expected-basic-image.bin").writeBytes(compiled.bytes)
            }
            val startAddress = address(decoded)
            val end = startAddress?.let { it + logical.size - 1 }
            writeJson(File(dir, "case.json"), buildJsonObject {
                put("id", id); put("machine", target); put("family", family); put("binary", input.binary)
                put("type", raw[0].toInt() and 255); put("transferName", name); put("bodyBytes", logical.size)
                put("bodySha256", logical.sha256()); put("rawSha256", raw.sha256()); put("wavSha256", wav.copyBytes().sha256())
                put("sampleRate", 8000); put("priority", input.priority)
                if (startAddress != null) { put("startAddress", startAddress); put("endAddress", end!!) }
            })
            index += "$id,$target,${if (input.binary) "binary" else "basic"},${raw[0].toInt().and(255).toString(16).padStart(2, '0')},${logical.size},${startAddress?.toString(16).orEmpty()},${end?.toString(16).orEmpty()},${input.priority},$id/send.wav"
        }
    }
    File(root, "cases.csv").writeText(index.joinToString("\n") + "\n")
    File(root, "results.csv").writeText("case_id,machine,rom_revision,recording_hz,connection,playback_level,pgp_to_device,device_to_pgp,body_match,address_match,type_match,filename_match,recording_file,notes\n" +
        index.drop(1).joinToString("\n") { row -> val c = row.split(','); "${c[0]},${c[1]},,,,,未実施,未実施,未実施,未実施,未実施,未実施,," } + "\n")
    println("Generated ${index.size - 1} valid cases under ${root.absolutePath}")
}

private fun checkHardwareRecording(caseDirectory: File, recording: File) {
    val manifest = Json.parseToJsonElement(File(caseDirectory, "case.json").readText()).jsonObject
    val result = DesktopWavOperation.decode(WavByteSequence(recording.readBytes()))
    val errors = result.diagnostics.filter { it.severity != CodecDiagnosticSeverity.INFO }
    val actualBody = if (result.validated) body(result) else null
    val expectedBody = File(caseDirectory, "expected-body.bin").readBytes()
    val isBinary = manifest.getValue("binary").jsonPrimitive.boolean
    val expectedAddress = manifest["startAddress"]?.jsonPrimitive?.int
    val bodyMatches = actualBody?.contentEquals(expectedBody) == true
    val addressMatches = !isBinary || address(result) == expectedAddress
    val typeMatches = result.raw?.unsignedByteAt(0) == manifest.getValue("type").jsonPrimitive.int
    val filenameMatches = result.transferFilename == manifest.getValue("transferName").jsonPrimitive.content
    val report = buildJsonObject {
        put("case", manifest.getValue("id")); put("recordingFile", recording.name)
        put("sampleRate", result.pcm?.sampleRate ?: 0); put("decoded", result.validated)
        put("bodyMatch", bodyMatches); put("addressMatch", addressMatches); put("typeMatch", typeMatches); put("filenameMatch", filenameMatches)
        put("checksumAndSignalClean", errors.isEmpty() && result.validated)
        put("programExportable", result.program != null)
        put("contentPass", bodyMatches && addressMatches && errors.isEmpty() && result.program != null)
        put("metadataPass", typeMatches && filenameMatches); put("diagnostics", result.report())
        if (actualBody != null) {
            val mismatch = (0 until minOf(actualBody.size, expectedBody.size)).firstOrNull { actualBody[it] != expectedBody[it] }
                ?: if (actualBody.size != expectedBody.size) minOf(actualBody.size, expectedBody.size) else null
            if (mismatch != null) put("firstDifferentBodyOffset", mismatch)
            put("actualBodyBytes", actualBody.size); put("actualBodySha256", actualBody.sha256())
        }
    }
    println(fixtureJson.encodeToString(JsonObject.serializer(), report))
    check(report.getValue("contentPass").jsonPrimitive.boolean) { "Recording does not match fixture; see report above" }
}
